const keyFor = (value: string) => value.trim().toLocaleLowerCase();
const BY_NAME = new Map(Object.entries(WEAPON_DESCRIPTIONS).map(([name, record]) => [keyFor(name), record]));

export function getWeaponDescription(name: string): WeaponDescriptionRecord | undefined {
  return BY_NAME.get(keyFor(name));
}
